// This file is a fakessh-local addition to the vendored x/crypto/ssh package.
// It registers OpenSSH 9.3 residual algorithms (diffie-hellman-group18-sha512
// and hmac-sha1-etm@openssh.com) without editing upstream core files. See
// third/AGENTS.md for upgrade notes.

package ssh

import (
	"crypto"
	"crypto/fips140"
	"crypto/hmac"
	"crypto/sha1"
	"hash"
	"math/big"
	"slices"
)

// OpenSSH 9.3 residual algorithm names that the vendored x/crypto/ssh package
// does not register by default. They are exported so callers can reference them
// from Config.KeyExchanges / Config.MACs.
const (
	// KeyExchangeDH18SHA512 is diffie-hellman-group18-sha512 from RFC 8268,
	// using the Oakley Group 18 (8192-bit) prime from RFC 3526.
	KeyExchangeDH18SHA512 = "diffie-hellman-group18-sha512"
	// HMACSHA1ETM is hmac-sha1-etm@openssh.com, the encrypt-then-MAC SHA-1
	// variant retained by OpenSSH 9.3 for legacy compatibility.
	HMACSHA1ETM = "hmac-sha1-etm@openssh.com"
)

// fakesshOakleyGroup18 is the 8192-bit MODP prime from RFC 3526, Oakley Group
// 18, used by diffie-hellman-group18-sha512 (RFC 8268).
const fakesshOakleyGroup18 = ""

func init() {
	// group18 and hmac-sha1-etm are skipped in FIPS 140 mode; hmac-sha1-etm
	// uses SHA-1, and group18 is kept out of the FIPS-only algorithm set.
	if fips140.Enabled() {
		return
	}

	p, _ := new(big.Int).SetString(fakesshOakleyGroup18, 16)
	kexAlgoMap[KeyExchangeDH18SHA512] = &dhGroup{
		g:        big.NewInt(2),
		p:        p,
		pMinus1:  new(big.Int).Sub(p, bigOne),
		hashFunc: crypto.SHA512,
	}
	supportedKexAlgos = fakesshInsertAfter(supportedKexAlgos, KeyExchangeDH16SHA512, KeyExchangeDH18SHA512)

	macModes[HMACSHA1ETM] = &macMode{20, true, func(key []byte) hash.Hash {
		return hmac.New(sha1.New, key)
	}}
	supportedMACs = fakesshInsertAfter(supportedMACs, HMACSHA512ETM, HMACSHA1ETM)
}

// fakesshInsertAfter inserts value into list immediately after the first
// occurrence of after. It is idempotent: if value is already present the list
// is returned unchanged. If after is absent, value is appended to the end.
func fakesshInsertAfter(list []string, after, value string) []string {
	if slices.Contains(list, value) {
		return list
	}
	for i, item := range list {
		if item == after {
			out := append(list[:i+1:i+1], value)
			out = append(out, list[i+1:]...)
			return out
		}
	}
	return append(list, value)
}
